const data = $input.item.json || {};
const remaining = Number(data.remaining ?? 0);
const count = Number(data.count ?? 0);
const limit = Number(data.limit ?? 450);
return { json: { daily_count: count, daily_limit: limit, daily_remaining: remaining, can_send: remaining >= 5 } };

let leads = [];
try { leads = $('Get Outreach Ready Leads').all(); } catch (e) {}
return { json: { run_complete: true, leads_attempted: leads.length, note: 'Per-lead outcomes are recorded in scan_errors (email_sent_log / email_sent_no_update / send_failed)', finished_at: new Date().toISOString() } };

const lead = $input.item.json;

// DEBUG: log what we received
console.log('Safety Check input:', JSON.stringify(lead, null, 2));

const skip = (reason) => ({ json: { ...lead, skip: true, reason, debug_msg: `Skipping because: ${reason}` } });

if (!lead) return skip('no_lead_data');
if (!lead.email || String(lead.email).trim() === '') return skip('no_email');
if (lead.do_not_contact === true) return skip('do_not_contact');
if (lead.unsubscribed === true) return skip('unsubscribed');
if ((Number(lead.total_emails_sent) || 0) >= 5) return skip('cap_reached');

const hoursSinceLastEmail = lead.last_email_sent_at 
  ? (Date.now() - new Date(lead.last_email_sent_at).getTime()) / 3600000 
  : 999;
if (hoursSinceLastEmail < 24) return skip('cooldown_24h');

if (!lead.email_subject || String(lead.email_subject).trim() === '') return skip('no_subject');
if (!lead.email_body || String(lead.email_body).trim() === '') return skip('no_body');

const unsubFooter = '<br><br><hr style="border:none;border-top:1px solid #ddd;margin:20px 0">' +
  '<p style="font-size:11px;color:#888;line-height:1.5">' +
  'You received this because your business was found in a public directory. ' +
  'If you prefer not to hear from us, <a href="mailto:unsubscribe@crystallux.org?subject=Unsubscribe%20' + 
  encodeURIComponent(lead.email || '') + '">click here to unsubscribe</a>.' +
  '<br>Crystallux | Ontario, Canada</p>';

const emailBody = String(lead.email_body || '').replace(/\n/g, '<br>') + unsubFooter;
return { 
  json: { 
    ...lead, 
    skip: false, 
    email_body_with_footer: emailBody,
    debug_msg: 'Safe to send. all checks passed'
  } 
};

// Build Gmail API raw message. RFC 2822 + base64url
// Replaces n8n Gmail node to eliminate unremovable 'sent with n8n' attribution.
// TESTING MODE. remove before production

const data = $input.item.json;
const to = 'adesholaakintunde+clxtest@gmail.com'; // TESTING MODE. remove before production
const subject = data.email_subject || '';
const htmlBody = data.email_body_with_footer || '';
const fromName = 'Mary Akintunde (Crystallux)';
const fromEmail = 'info@crystallux.org';

// RFC 2047 encode subject for UTF-8 safety
const encodedSubject = '=?UTF-8?B?' + Buffer.from(subject, 'utf8').toString('base64') + '?=';

const mime = [
  'From: "' + fromName + '" <' + fromEmail + '>',
  'To: ' + to,
  'Subject: ' + encodedSubject,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=utf-8',
  'Content-Transfer-Encoding: 7bit',
  '',
  htmlBody
].join('\r\n');

// base64url (RFC 4648)
const raw = Buffer.from(mime, 'utf8').toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return { json: { ...data, gmail_raw: raw } };

const incoming = $input.item.json || {};
const lead = $('Safety Check').item.json || {};
const errorObj = incoming.error || $input.item.error;
const sendOk = !errorObj && !!(incoming.id || incoming.threadId || incoming.labelIds || incoming.messageId);
return { json: { ...lead, send_ok: sendOk, send_error: errorObj ? (errorObj.message || (typeof errorObj === 'string' ? errorObj : JSON.stringify(errorObj))) : null, gmail_message_id: incoming.id || incoming.messageId || null, gmail_thread_id: incoming.threadId || null } };

const item = $input.item.json;
const now = new Date();
const followupDate = new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000);
const clientObj = item.clients || {};
return { json: { ...item, p_lead_id: item.id, p_outreach_sent_at: now.toISOString(), p_followup_scheduled_at: followupDate.toISOString(), p_lead_status: 'Contacted', p_outreach_channel: 'email', p_total_emails_sent: (Number(item.total_emails_sent) || 0) + 1, p_last_email_sent_at: now.toISOString(), client_notification_email: clientObj.notification_email || null, client_calendly_link: clientObj.calendly_link || null } };

const item = $input.item.json || {};
const errorObj = item.error || $input.item.error;
const updateFailed = !!errorObj;
return { json: { workflow_name: 'CLX-Outreach-Sender-v2', node_name: updateFailed ? 'email_sent_no_update' : 'email_sent_log', error_code: updateFailed ? 'UPDATE_FAILED_AFTER_SEND' : 'OK', error_message: updateFailed ? ('Email sent but lead update failed: ' + (errorObj.message || JSON.stringify(errorObj))) : 'Email sent and lead updated', input_data: { lead_id: item.p_lead_id || item.id, recipient: item.email, subject: item.email_subject, gmail_message_id: item.gmail_message_id, gmail_thread_id: item.gmail_thread_id, city: item.city, industry: item.industry, client_id: item.client_id, client_notification_email: item.client_notification_email, sent_at: item.p_outreach_sent_at } } };

// Final send boundary. 'Outreach Ready' is a queue position, not permission.
//
// A house lead with no owner and no research was emailed on 2026-08-31
// because every stage upstream filtered on lead_status alone, and the
// sender's own checks were all about consent -- none asked whether we had
// any business contacting this person.
//
// Every condition below is fail-closed: missing state refuses. Absence is
// never read as permission.

const allOf = function (name) {
  try {
    const items = $(name).all().map(function (i) { return i.json; });
    if (items.length === 1 && Array.isArray(items[0])) return items[0];
    return items;
  } catch (e) { return []; }
};

const leads = allOf('Get Outreach Ready Leads');
const clients = allOf('Fetch Client Send Policy');
const campaigns = allOf('Fetch Authorized Campaigns');
const users = allOf('Fetch Entitled Tenants');
const personas = allOf('Fetch Autonomy Levels');

const REQUIRED_POOL = 'tenant';
const PRODUCT = 'sales_engine';
const CHANNEL = 'email';
// Only these may execute a contact without a human in the loop. Anything
// else -- recommend_only included -- proposes and waits.
const AUTONOMY_MAY_EXECUTE = ['full_autonomy', 'execute'];

const clientById = {};
clients.forEach(function (c) { if (c && c.id) clientById[c.id] = c; });

// Entitlement mirrors check_product_entitlement: the tenant is entitled
// when at least one ACTIVE user holds the product. Computed once for the
// batch rather than one RPC per lead.
const entitled = {};
users.forEach(function (u) {
  if (!u || !u.client_id) return;
  let ps = u.products;
  if (typeof ps === 'string') { try { ps = JSON.parse(ps); } catch (e) { ps = []; } }
  if (Array.isArray(ps) && ps.indexOf(PRODUCT) >= 0) entitled[u.client_id] = true;
});

const authorized = {};
campaigns.forEach(function (c) {
  if (c && c.client_id && c.status === 'active') {
    authorized[c.client_id + '|' + (c.channel || CHANNEL)] = true;
  }
});

const autonomy = {};
personas.forEach(function (p) {
  if (p && p.client_id) autonomy[p.client_id] = p.autonomy_level || null;
});

function channelEnabled(client) {
  if (!client) return false;
  let ch = client.channels_enabled;
  if (typeof ch === 'string') { try { ch = JSON.parse(ch); } catch (e) { ch = []; } }
  return Array.isArray(ch) && ch.indexOf(CHANNEL) >= 0;
}

// A scoring failure must not read as a business fact. The scorer leaves a
// failed lead unscored rather than writing 0, so an absent score is an
// absent judgement -- not a low one.
function scoreIsValid(l) {
  if (l.lead_score === null || l.lead_score === undefined) return false;
  if (typeof l.lead_score !== 'number' || l.lead_score <= 0) return false;
  const reason = String(l.scoring_reason || '');
  if (/error|failed|unavailable|parse/i.test(reason)) return false;
  return true;
}

const eligible = [];
const refused = [];

leads.forEach(function (l) {
  const why = [];
  const client = clientById[l.client_id];

  if (!l.client_id) why.push('no owning client');
  if (l.lead_pool !== REQUIRED_POOL) why.push('lead_pool=' + (l.lead_pool || 'null'));
  if (!l.research_summary || !String(l.research_summary).trim()) why.push('no research');
  if (!scoreIsValid(l)) why.push('no valid score');
  if (!l.email || String(l.email).indexOf('@') < 0) why.push('no usable email');

  if (l.unsubscribed) why.push('unsubscribed');
  if (l.do_not_contact) why.push('do_not_contact');
  if (l.reply_detected) why.push('reply already received');
  if ((l.total_emails_sent || 0) >= 5) why.push('send limit reached');
  if (l.source === 'test') why.push('test source');

  if (!client) why.push('tenant not found');
  else if (client.onboarding_stage !== 'active') why.push('tenant not active');

  if (!entitled[l.client_id]) why.push('tenant lacks ' + PRODUCT + ' entitlement');
  if (!channelEnabled(client)) why.push(CHANNEL + ' not enabled for tenant');
  if (!authorized[l.client_id + '|' + CHANNEL]) why.push('no authorized campaign');

  const level = autonomy[l.client_id];
  if (!level) why.push('no autonomy level set');
  else if (AUTONOMY_MAY_EXECUTE.indexOf(level) < 0) {
    why.push('autonomy=' + level + ' proposes only');
  }

  if (why.length) refused.push({ id: l.id, company: l.company || null, reasons: why });
  else eligible.push({ json: l });
});

// Recorded, not silently dropped: a queue that stops moving with no
// explanation is how the original problem went unnoticed.
console.log('[sender-guard] queued=' + leads.length + ' eligible=' + eligible.length +
            ' refused=' + refused.length);
if (refused.length) {
  console.log('[sender-guard] refusals: ' + JSON.stringify(refused.slice(0, 25)));
}

return eligible;
